## Why This Is Asked
This question tests mastery of three key concepts: Trie mutations (insert/delete), weighted dynamic programming for word break problems, and the ability to implement both iterative and recursive approaches. It also evaluates understanding of handling dynamic dictionary updates and edge cases such as when no valid decomposition exists.

## Key Concepts
- Trie with terminal weights for efficient prefix matching
- Dynamic insert/delete operations on Trie structure
- Weighted word-break DP with O(n × L) complexity where L = maxWordLen
- Both iterative bottom-up DP and memoized top-down DFS variants

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.children = new Map();
    this.endWeight = 0;
    this.isEnd = false;
  }
}

class WeightedTrie {
  constructor() {
    this.root = new TrieNode();
    this.maxWordLen = 0;
  }

  insert(word, weight) {
    let node = this.root;
    for (const char of word) {
      if (!node.children.has(char)) {
        node.children.set(char, new TrieNode());
      }
      node = node.children.get(char);
    }
    node.isEnd = true;
    node.endWeight = weight;
    this.maxWordLen = Math.max(this.maxWordLen, word.length);
  }

  delete(word) {
    let node = this.root;
    for (const char of word) {
      if (!node.children.has(char)) return;
      node = node.children.get(char);
    }
    node.isEnd = false;
    node.endWeight = 0;
  }

  maxPartition(s) {
    const n = s.length;
    const dp = new Array(n + 1).fill(-1);
    dp[n] = 0;

    for (let i = n - 1; i >= 0; i--) {
      let node = this.root;
      for (let j = i; j < Math.min(n, i + this.maxWordLen); j++) {
        const char = s[j];
        if (!node.children.has(char)) break;
        node = node.children.get(char);
        if (node.isEnd && dp[j + 1] !== -1) {
          dp[i] = Math.max(dp[i], node.endWeight + dp[j + 1]);
        }
      }
    }
    return dp[0];
  }

  maxPartitionDFS(s, memo = {}) {
    if (s.length === 0) return 0;
    if (s in memo) return memo[s];

    let maxWeight = -1;
    let node = this.root;

    for (let i = 0; i < Math.min(s.length, this.maxWordLen); i++) {
      const char = s[i];
      if (!node.children.has(char)) break;
      node = node.children.get(char);

      if (node.isEnd) {
        const remaining = this.maxPartitionDFS(s.slice(i + 1), memo);
        if (remaining !== -1) {
          maxWeight = Math.max(maxWeight, node.endWeight + remaining);
        }
      }
    }
    memo[s] = maxWeight;
    return maxWeight;
  }
}
```

## Why This Question Is Asked

This problem tests your ability to combine multiple data structures to solve a real-world analytics challenge: maintaining sliding window aggregations with fast top-K retrieval under tight latency constraints.

## Key Concepts

1. **Circular bucket array** enables O(1) bucketing and automatic expiration of old events
2. **Hashmap aggregation** provides O(1) lookup and update for per-user totals across categories
3. **Max-heap with lazy deletion** avoids the overhead of rebuilding the heap on every expiration; stale entries are filtered on-demand during `topK`
4. **Lazy expiration** ensures we never scan individual events during query time—only expired buckets trigger cleanup

## Code Example

```javascript
class WindowedTopK {
  constructor(W) {
    this.W = W;
    this.buckets = new Array(W).fill(null).map(() => ({ head: null, tail: null, ts: null }));
    this.totals = new Map();
    this.heap = [];
    this.head = 0;
  }

  insertEvent(ts, userId, category, value) {
    const idx = ts % this.W;
    const bucket = this.buckets[idx];
    const event = { userId, category, value, ts, next: null };
    if (!bucket.head) bucket.head = bucket.tail = event;
    else bucket.tail = bucket.tail.next = event;
    bucket.ts = ts;

    this.totals.set(userId, (this.totals.get(userId) || 0) + value);
    this.heap.push({ total: this.totals.get(userId), userId, ts });
  }

  advanceTime(now) {
    const cutoff = now - this.W;
    while (this.buckets[this.head].ts !== null && this.buckets[this.head].ts < cutoff) {
      let event = this.buckets[this.head].head;
      while (event) {
        this.totals.set(event.userId, (this.totals.get(event.userId) || 0) - event.value);
        event = event.next;
      }
      this.buckets[this.head] = { head: null, tail: null, ts: null };
      this.head = (this.head + 1) % this.W;
    }
  }

  topK(now, K) {
    this.advanceTime(now);
    const result = [];
    let i = 0;
    while (result.length < K && i < this.heap.length) {
      const entry = this.heap[i++];
      if (this.totals.get(entry.userId) === entry.total) {
        result.push(entry.userId);
      }
    }
    return result;
  }
}
```

